```cpp
void setup() {
  Serial.begin(9600);
  float x = 0.5, y = 0.5, z = 1.0;
  float g = sqrt(x * x + y * y + z * z);
  if (g < 0.8 || g > 1.2) Serial.println("HATA");
  else Serial.println("TAMAM");
}
void loop() {}
```

